import java.util.HashMap;
import java.util.Map;

// Data model shared by all layers
class Order {
    int orderId;
    String customerName;
    double amount;

    Order(int orderId, String customerName, double amount) {
        this.orderId = orderId;
        this.customerName = customerName;
        this.amount = amount;
    }
}

// Data Access Layer
class OrderRepository {
    private final Map<Integer, Order> store = new HashMap<>(); // stands in for a real database
    private int nextId = 1;

    Order save(Order order) {
        order.orderId = nextId++;
        store.put(order.orderId, order); // pure storage, no business rules here
        return order;
    }

    Order findById(int orderId) {
        return store.get(orderId);
    }
}

// Business Layer
class OrderService {
    private final OrderRepository repository; // service only ever talks to the layer below it

    OrderService(OrderRepository repository) {
        this.repository = repository;
    }

    Order placeOrder(String customerName, double amount) {
        double finalAmount = amount;
        if (amount > 100) {
            finalAmount = amount * 0.9; // business rule: bulk discount lives here, nowhere else
        }
        Order order = new Order(0, customerName, finalAmount);
        return repository.save(order); // hands off to data access, never touches storage itself
    }
}

// Presentation Layer
class OrderController {
    private final OrderService service; // controller only ever talks to the layer below it

    OrderController(OrderService service) {
        this.service = service;
    }

    void handlePlaceOrder(String customerName, double amount) {
        Order saved = service.placeOrder(customerName, amount); // never reaches into the repository directly
        System.out.println("Order #" + saved.orderId + " for " + saved.customerName + " confirmed at " + saved.amount);
    }
}

public class Main {
    public static void main(String[] args) {
        OrderRepository repository = new OrderRepository();
        OrderService service = new OrderService(repository);
        OrderController controller = new OrderController(service);

        controller.handlePlaceOrder("Asha", 150); // above 100, discount applies
        controller.handlePlaceOrder("Raj", 40);    // below 100, no discount
    }
}

