#include <iostream>
#include <string>
#include <unordered_map>
using namespace std;

// Data model shared by all layers
struct Order {
    int orderId;
    string customerName;
    double amount;
};

// Data Access Layer
class OrderRepository {
private:
    unordered_map<int, Order> store; // stands in for a real database
    int nextId = 1;

public:
    Order save(Order order) {
        order.orderId = nextId++;
        store[order.orderId] = order; // pure storage, no business rules here
        return order;
    }

    Order findById(int orderId) {
        return store[orderId];
    }
};

// Business Layer
class OrderService {
private:
    OrderRepository& repository; // service only ever talks to the layer below it

public:
    OrderService(OrderRepository& repository) : repository(repository) {}

    Order placeOrder(string customerName, double amount) {
        double finalAmount = amount;
        if (amount > 100) {
            finalAmount = amount * 0.9; // business rule: bulk discount lives here, nowhere else
        }
        Order order{0, customerName, finalAmount};
        return repository.save(order); // hands off to data access, never touches storage itself
    }
};

// Presentation Layer
class OrderController {
private:
    OrderService& service; // controller only ever talks to the layer below it

public:
    OrderController(OrderService& service) : service(service) {}

    void handlePlaceOrder(string customerName, double amount) {
        Order saved = service.placeOrder(customerName, amount); // never reaches into the repository directly
        cout << "Order #" << saved.orderId << " for " << saved.customerName << " confirmed at " << saved.amount << endl;
    }
};

int main() {
    OrderRepository repository;
    OrderService service(repository);
    OrderController controller(service);

    controller.handlePlaceOrder("Asha", 150); // above 100, discount applies
    controller.handlePlaceOrder("Raj", 40);    // below 100, no discount
    return 0;
}
